"""obsd.tsdb - series identity, idempotent writes, bucketed query, retention.

Standard library only. All logic takes an explicit clock (``now``) where time
matters; nothing here calls time.time().
"""

from __future__ import annotations

import hashlib
import json
import os
import threading

__all__ = ["ObsError", "SeriesStore", "AGGREGATES", "canonical_identity", "series_id_for"]

AGGREGATES = ("sum", "avg", "min", "max", "count")


class ObsError(Exception):
    """Raised for any rejected observation or request."""


def _num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _labels_list(labels):
    """Normalise labels to a list of ``[key, value]`` pairs sorted by key."""
    if labels is None:
        return []
    if isinstance(labels, dict):
        items = list(labels.items())
    elif isinstance(labels, (list, tuple)):
        items = []
        for entry in labels:
            if not isinstance(entry, (list, tuple)) or len(entry) != 2:
                raise ObsError("labels entries must be [key, value] pairs")
            items.append((entry[0], entry[1]))
    else:
        raise ObsError("labels must be an object or a list of pairs")
    pairs = []
    for key, value in items:
        if not isinstance(key, str) or value is None:
            raise ObsError("label keys must be strings and values must not be null")
        pairs.append([key, str(value)])
    pairs.sort(key=lambda pair: pair[0])
    if len({key for key, _ in pairs}) != len(pairs):
        raise ObsError("duplicate label key")
    return pairs


def as_labels(labels):
    """Normalise labels to a plain dict."""
    return {key: value for key, value in _labels_list(labels)}


def canonical_identity(tenant, metric, labels):
    """Canonical newline-joined identity string of a series."""
    if not isinstance(tenant, str) or not tenant:
        raise ObsError("tenant must be a non-empty string")
    if not isinstance(metric, str) or not metric:
        raise ObsError("metric must be a non-empty string")
    return "\n".join([tenant, metric] +
                     ["%s=%s" % (key, value) for key, value in _labels_list(labels)])


def series_id_for(tenant, metric, labels):
    """64-char sha256 id of a series, independent of label insertion order."""
    return hashlib.sha256(canonical_identity(tenant, metric, labels).encode("utf-8")).hexdigest()


def matches_labels(series_labels, matcher):
    """True when every matcher pair is present in ``series_labels``."""
    if not matcher:
        return True
    if isinstance(matcher, (list, tuple)):
        matcher = as_labels(matcher)
    return all(str(series_labels.get(key)) == str(value) for key, value in matcher.items())


def _aggregate(values, agg):
    if agg == "sum":
        return float(sum(values))
    if agg == "avg":
        return sum(values) / float(len(values))
    if agg == "min":
        return float(min(values))
    if agg == "max":
        return float(max(values))
    if agg == "count":
        return len(values)
    raise ObsError("unknown aggregation: %r" % (agg,))


def _atomic_write(path, text):
    """Write ``text`` to ``path`` through a temp file plus os.replace."""
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(path + ".tmp", "w", encoding="utf-8") as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(path + ".tmp", path)


def _line(stamp, value):
    return json.dumps({"t": stamp, "v": value}, separators=(",", ":")) + "\n"


class SeriesStore:
    """Append-mostly time series store persisted under ``root``.

    Layout::

        <root>/series.json                 registry: series_id -> series row
        <root>/points/<series_id>.jsonl    one ``{"t":ts,"v":value}`` per line
    """

    def __init__(self, root):
        if not isinstance(root, (str, os.PathLike)) or not str(root):
            raise ObsError("root must be a non-empty path")
        self.root = os.path.abspath(str(root))
        self.points_dir = os.path.join(self.root, "points")
        self.series_path = os.path.join(self.root, "series.json")
        self._lock = threading.RLock()
        self._series, self._samples, self._writes = {}, {}, 0
        os.makedirs(self.points_dir, exist_ok=True)
        self._load()

    def _points_path(self, sid):
        return os.path.join(self.points_dir, sid + ".jsonl")

    # ------------------------------------------------------------- persistence
    def _load(self):
        rows = []
        if os.path.exists(self.series_path):
            try:
                with open(self.series_path, "r", encoding="utf-8") as handle:
                    rows = json.load(handle)
            except (OSError, ValueError) as exc:
                raise ObsError("cannot read series registry: %s" % exc)
        for row in rows:
            sid = row.get("series_id")
            if not sid:
                continue
            self._series[sid] = {"series_id": sid, "tenant": row.get("tenant"),
                                 "metric": row.get("metric"),
                                 "labels": [[str(k), str(v)] for k, v in row.get("labels", [])],
                                 "identity": row.get("identity")}
            self._samples[sid] = self._read_points(sid)

    def _read_points(self, sid):
        """Reload one point file, skipping unreadable lines."""
        rows = []
        path = self._points_path(sid)
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as handle:
                for line in handle:
                    try:
                        row = json.loads(line)
                        rows.append((int(row["t"]), float(row["v"])))
                    except (ValueError, KeyError, TypeError):
                        continue
        return sorted(rows)

    def _save_registry(self):
        _atomic_write(self.series_path, json.dumps(
            [self._series[sid] for sid in sorted(self._series)],
            sort_keys=True, separators=(",", ":")))

    def _rewrite_points(self, sid):
        _atomic_write(self._points_path(sid),
                      "".join(_line(ts, value) for ts, value in self._samples[sid]))

    # ------------------------------------------------------------------- write
    def _ensure_series(self, tenant, metric, labels):
        pairs = _labels_list(labels)
        identity = canonical_identity(tenant, metric, pairs)
        sid = hashlib.sha256(identity.encode("utf-8")).hexdigest()
        if sid not in self._series:
            self._series[sid] = {"series_id": sid, "tenant": tenant, "metric": metric,
                                 "labels": pairs, "identity": identity}
            self._samples[sid] = []
        return sid

    def write(self, tenant, metric, labels, samples, now=None, overwrite=False):
        """Store ``samples`` = ``[(timestamp_ms, value), ...]``.

        Idempotent: an identical ``(series, timestamp)`` value is a duplicate
        and changes nothing. A differing value for a stored timestamp raises
        ``ObsError`` unless ``overwrite=True``.
        """
        if not isinstance(samples, (list, tuple)):
            raise ObsError("samples must be a list of [timestamp_ms, value] pairs")
        clean = []
        for entry in samples:
            if not isinstance(entry, (list, tuple)) or len(entry) != 2:
                raise ObsError("each sample must be a [timestamp_ms, value] pair")
            stamp, value = entry
            if not _num(stamp) or not _num(value):
                raise ObsError("sample timestamp and value must be numbers")
            if now is not None and int(stamp) > int(now):
                raise ObsError("sample timestamp %d is in the future (now=%d)"
                               % (int(stamp), int(now)))
            clean.append((int(stamp), float(value)))
        if not clean:
            raise ObsError("samples must not be empty")
        with self._lock:
            sid = self._ensure_series(tenant, metric, labels)
            merged = dict(self._samples[sid])
            written = duplicates = 0
            fresh = []
            for stamp, value in clean:
                if stamp in merged and merged[stamp] != value and not overwrite:
                    raise ObsError("conflict for %s at timestamp %d: stored=%r incoming=%r"
                                   % (sid, stamp, merged[stamp], value))
                if stamp in merged and merged[stamp] == value:
                    duplicates += 1
                    continue
                merged[stamp] = value
                fresh.append((stamp, value))
                written += 1
            if fresh:
                self._samples[sid] = sorted(merged.items())
                with open(self._points_path(sid), "a", encoding="utf-8") as handle:
                    handle.write("".join(_line(ts, value) for ts, value in sorted(fresh)))
                    handle.flush()
                    os.fsync(handle.fileno())
                self._writes += 1
                self._save_registry()
        return {"series_id": sid, "written": written, "duplicates": duplicates}

    # ------------------------------------------------------------------- query
    def _samples_for(self, tenant, metric, labels):
        with self._lock:
            ids = sorted(sid for sid, row in self._series.items()
                         if row["tenant"] == tenant and row["metric"] == metric
                         and matches_labels(dict(row["labels"]), labels))
            return [(sid, list(self._samples[sid])) for sid in ids]

    def _scan(self, tenant, metric, labels, start_ms, end_ms):
        """Raw samples of matching series inside ``[start, end]`` (internal).

        Used where exact event counts matter (SLO numerator/denominator) and by
        rule evaluation to find candidate series.
        """
        lo = None if start_ms is None else int(start_ms)
        hi = None if end_ms is None else int(end_ms)
        out = []
        for sid, samples in self._samples_for(tenant, metric, labels):
            rows = [item for item in samples
                    if (lo is None or item[0] >= lo) and (hi is None or item[0] <= hi)]
            if rows:
                out.append((sid, rows))
        return out

    def query(self, tenant, metric, labels=None, start_ms=None, end_ms=None,
              step_ms=None, agg=None):
        """Raw or bucketed points per matching series.

        ``step_ms`` buckets are left-closed/right-open on epoch multiples and
        empty buckets are emitted as ``None``. A series with no sample in range
        is still listed, with an empty ``points`` list, unless ``agg`` is used
        without ``step_ms`` (then it yields nothing and is omitted).
        """
        if agg is not None and agg not in AGGREGATES:
            raise ObsError("unknown aggregation: %r" % (agg,))
        if step_ms is not None and (not _num(step_ms) or int(step_ms) <= 0):
            raise ObsError("step_ms must be a positive number")
        lo = None if start_ms is None else int(start_ms)
        hi = None if end_ms is None else int(end_ms)
        if lo is not None and hi is not None and hi < lo:
            raise ObsError("end_ms must be >= start_ms")
        out = []
        for sid, samples in self._samples_for(tenant, metric, labels):
            rows = [item for item in samples
                    if (lo is None or item[0] >= lo) and (hi is None or item[0] <= hi)]
            points = self._bucket(rows, step_ms, agg, lo, hi)
            if points is None or (not points and agg is not None and step_ms is None):
                continue
            out.append({"series_id": sid, "labels": dict(self._series[sid]["labels"]),
                        "points": points})
        return out

    def _bucket(self, rows, step_ms, agg, lo, hi):
        """``None`` = nothing to report, ``[]`` = known empty, else the points."""
        if step_ms is None:
            if agg is None:
                return [[stamp, value] for stamp, value in rows]
            return None if not rows else [[rows[0][0], _aggregate([v for _, v in rows], agg)]]
        step = int(step_ms)
        groups = {}
        for stamp, value in rows:
            groups.setdefault(stamp - (stamp % step), []).append(value)
        if not groups:
            return None
        keys = sorted(groups)
        start = max(keys[0], lo - (lo % step)) if lo is not None else keys[0]
        end = min(keys[-1], hi - (hi % step)) if hi is not None else keys[-1]
        return [[key, _aggregate(groups[key], agg) if key in groups else None]
                for key in range(start, end + 1, step)]

    def rollup(self, tenant, metric, labels, window_ms, agg):
        """Downsampled series over the whole stored range, ordered by series_id."""
        if agg not in AGGREGATES:
            raise ObsError("unknown aggregation: %r" % (agg,))
        if not _num(window_ms) or int(window_ms) <= 0:
            raise ObsError("window_ms must be a positive number")
        return [{"series_id": item["series_id"], "labels": item["labels"],
                 "points": [point for point in item["points"] if point[1] is not None]}
                for item in self.query(tenant, metric, labels=labels,
                                       step_ms=int(window_ms), agg=agg)]

    # --------------------------------------------------------------- retention
    def enforce_retention(self, tenant, cutoff_ms):
        """Drop every sample with ``timestamp_ms < cutoff_ms`` for ``tenant``."""
        cutoff = int(cutoff_ms)
        dropped = affected = 0
        with self._lock:
            for sid in sorted(self._series):
                if self._series[sid]["tenant"] != tenant:
                    continue
                keep = [item for item in self._samples[sid] if item[0] >= cutoff]
                removed = len(self._samples[sid]) - len(keep)
                if removed:
                    self._samples[sid] = keep
                    self._rewrite_points(sid)
                    dropped += removed
                    affected += 1
        return {"dropped": dropped, "series": affected, "cutoff_ms": cutoff}

    def stats(self):
        with self._lock:
            per_tenant = {}
            points = 0
            for sid, row in self._series.items():
                count = len(self._samples[sid])
                points += count
                entry = per_tenant.setdefault(row["tenant"], {"series": 0, "points": 0})
                entry["series"] += 1
                entry["points"] += count
        return {"series": len(self._series), "points": points, "writes": self._writes,
                "tenants": per_tenant}

"""obsd.http_app - stdlib ThreadingHTTPServer JSON API."""

from __future__ import annotations

import json
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

from .alerts import AlertEngine
from .tsdb import ObsError, SeriesStore

__all__ = ["ObsdHTTPServer", "create_server", "make_handler", "run_server"]


def _int(value, field, default=None):
    if value is None or value == "":
        return default
    try:
        return int(value)
    except (TypeError, ValueError):
        raise ObsError("%s must be an integer" % field)
def _float(value, field):
    try:
        return float(value)
    except (TypeError, ValueError):
        raise ObsError("%s must be a number" % field)
def _require(payload, key):
    if payload.get(key) is None:
        raise ObsError("missing field: %s" % key)
    return payload[key]
def _labels(payload):
    value = payload.get("labels") or {}
    if not isinstance(value, dict):
        raise ObsError("labels must be an object")
    return value
def dispatch(store, engine, method, path, params, payload):
    """Pure routing: (status, body) or ObsError. No sockets involved."""
    labels = {key[6:]: value for key, value in params.items() if key.startswith("label.")}
    if (method, path) == ("GET", "/healthz"):
        return 200, {"ok": True}
    if (method, path) == ("GET", "/v1/stats"):
        return 200, {"store": store.stats(), "alerts": len(engine.list_alerts())}
    if (method, path) == ("POST", "/v1/series"):
        result = store.write(_require(payload, "tenant"), _require(payload, "metric"),
                             _labels(payload), _require(payload, "samples"),
                             now=payload.get("now_ms"),
                             overwrite=bool(payload.get("overwrite", False)))
        return 202, {"written": result["written"], "duplicates": result["duplicates"],
                     "series_id": result["series_id"]}
    if (method, path) == ("GET", "/v1/query"):
        rows = store.query(_require(params, "tenant"), _require(params, "metric"), labels=labels,
                           start_ms=_int(params.get("start"), "start"),
                           end_ms=_int(params.get("end"), "end"),
                           step_ms=_int(params.get("step"), "step"),
                           agg=params.get("agg") or None)
        return 200, {"series": [{"labels": row["labels"], "points": row["points"]}
                                for row in rows]}
    if (method, path) == ("POST", "/v1/rules"):
        return 201, engine.add_rule(payload)
    if (method, path) == ("GET", "/v1/rules"):
        return 200, {"rules": engine.list_rules(params.get("tenant"))}
    if (method, path) == ("POST", "/v1/evaluate"):
        return 200, engine.evaluate(_int(_require(payload, "now_ms"), "now_ms"))
    if (method, path) == ("GET", "/v1/alerts"):
        return 200, {"alerts": engine.list_alerts(params.get("tenant"), params.get("state"))}
    if (method, path) == ("POST", "/v1/silences"):
        return 201, engine.add_silence(_require(payload, "tenant"), _labels(payload),
                                       _require(payload, "starts_ms"),
                                       _require(payload, "ends_ms"), payload.get("reason", ""))
    if (method, path) == ("POST", "/v1/inhibitions"):
        return 201, engine.add_inhibition(_require(payload, "source_severity"),
                                          _require(payload, "target_severity"),
                                          bool(payload.get("same_labels", True)))
    if (method, path) == ("POST", "/v1/slos"):
        return 201, engine.set_slo(_require(payload, "tenant"), _require(payload, "name"),
                                   _require(payload, "metric"), _labels(payload),
                                   _require(payload, "good_comparator"),
                                   _float(_require(payload, "threshold"), "threshold"),
                                   _float(_require(payload, "target_ratio"), "target_ratio"),
                                   _require(payload, "window_ms"))
    if (method, path) == ("GET", "/v1/slos"):
        return 200, {"slos": engine.list_slos(params.get("tenant"))}
    if (method, path) == ("GET", "/v1/slos/status"):
        now = _int(params.get("now_ms"), "now_ms", int(time.time() * 1000))
        return 200, engine.slo_status(_require(params, "name"), now, tenant=params.get("tenant"))
    raise ObsError("not found: %s %s" % (method, path))
def _status_for(message):
    if message.startswith(("not found", "unknown")):
        return 404
    return 409 if message.startswith("conflict") else 400
def make_handler(store, engine):
    class ObsdHandler(BaseHTTPRequestHandler):
        server_version = "obsd/0.1"
        sys_version = ""
        protocol_version = "HTTP/1.1"

        def log_message(self, fmt, *args):
            """Keep stdout clean: every line printed is a JSON payload."""
        def _read_json(self):
            length = _int(self.headers.get("Content-Length"), "Content-Length", 0) or 0
            if not length:
                return {}
            try:
                payload = json.loads(self.rfile.read(length).decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                raise ObsError("invalid JSON body")
            if not isinstance(payload, dict):
                raise ObsError("JSON body must be an object")
            return payload
        def _send(self, status, body):
            data = json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def _handle(self, method, call):
            parsed = urlparse(self.path)
            params = {key: values[-1] for key, values in parse_qs(parsed.query).items()}
            try:
                payload = self._read_json() if method == "POST" else {}
                status, body = call(parsed.path, params, payload)
            except ObsError as exc:
                self._send(_status_for(str(exc)), {"error": str(exc)})
                return
            except Exception as exc:  # pragma: no cover - defensive
                self._send(500, {"error": "internal error: %s" % exc})
                return
            self._send(status, body)
        def do_GET(self):
            self._handle("GET", lambda path, params, payload:
                         dispatch(store, engine, "GET", path, params, payload))
        def do_POST(self):
            self._handle("POST", lambda path, params, payload:
                         dispatch(store, engine, "POST", path, params, payload))
        def do_DELETE(self):
            def call(path, params, payload):
                if not path.startswith("/v1/rules/"):
                    raise ObsError("not found: DELETE %s" % path)
                return 200, engine.del_rule(path.rsplit("/", 1)[-1])
            self._handle("DELETE", call)
    return ObsdHandler
class ObsdHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address, store, engine):
        self.store = store
        self.engine = engine
        super().__init__(address, make_handler(store, engine))
def create_server(store, engine, host="127.0.0.1", port=8080):
    """Build (but do not start) a ThreadingHTTPServer bound to ``host:port``."""
    if not isinstance(store, SeriesStore):
        raise ObsError("store must be a SeriesStore")
    if not isinstance(engine, AlertEngine):
        raise ObsError("engine must be an AlertEngine")
    return ObsdHTTPServer((host, int(port)), store, engine)
def run_server(store, engine, host="127.0.0.1", port=8080):
    """Serve until interrupted; prints one JSON startup line on stdout."""
    server = create_server(store, engine, host, port)
    print(json.dumps({"ok": True, "listening": "http://%s:%d" % server.server_address[:2],
                      "data_dir": store.root}, sort_keys=True, separators=(",", ":")), flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
    return 0

"""obsd.alerts - rules, evaluation, silence/inhibition, dedup and SLO math.

All time is injected through ``now_ms``; nothing here reads the wall clock.
"""

from __future__ import annotations

import copy
import json
import os
import threading

from .tsdb import ObsError, _atomic_write, _labels_list, matches_labels

__all__ = ["AlertEngine", "COMPARATORS", "AGGREGATES", "SEVERITIES", "STATE_FIRING",
           "STATE_SILENCED", "STATE_INHIBITED", "STATE_RESOLVED"]
COMPARATORS = (">", ">=", "<", "<=", "==", "!=")
AGGREGATES = ("sum", "avg", "min", "max", "count")
SEVERITIES = ("info", "warning", "critical")
SEVERITY_RANK = {"info": 1, "warning": 2, "critical": 3}
STATE_FIRING = "firing"
STATE_SILENCED = "silenced"
STATE_INHIBITED = "inhibited"
STATE_RESOLVED = "resolved"
ACTIVE_STATES = (STATE_FIRING, STATE_SILENCED, STATE_INHIBITED)
_FILES = ("rules", "alerts", "slos", "silences", "inhibitions", "counters")


def _is_num(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)
def _require_int(value, field):
    if not _is_num(value) or int(value) != value:
        raise ObsError("%s must be an integer" % field)
    return int(value)
def compare(value, comparator, threshold):
    """Apply ``comparator`` to a bucket value; ``None`` never satisfies."""
    if value is None:
        return False
    if comparator == ">":
        return value > threshold
    if comparator == ">=":
        return value >= threshold
    if comparator == "<":
        return value < threshold
    if comparator == "<=":
        return value <= threshold
    if comparator == "==":
        return value == threshold
    if comparator == "!=":
        return value != threshold
    raise ObsError("unknown comparator: %r" % (comparator,))
class AlertEngine:
    """Rule evaluation with dedup, silences, inhibition and SLO tracking.

    Persisted under ``root`` as rules.json, alerts.json, slos.json,
    silences.json, inhibitions.json and counters.json (atomic writes); a new
    instance reloads all of it, so alerts and rules survive a restart.
    """

    def __init__(self, store, root):
        if store is None:
            raise ObsError("store is required")
        if not isinstance(root, (str, os.PathLike)) or not str(root):
            raise ObsError("root must be a non-empty path")
        self.store = store
        self.root = os.path.abspath(str(root))
        self._lock = threading.RLock()
        self._rules, self._silences, self._inhibitions, self._slos, self._alerts = {}, {}, {}, {}, {}
        self._counters = {"rule": 0, "silence": 0, "inhibition": 0, "alert": 0}
        os.makedirs(self.root, exist_ok=True)
        self._load()
    # ------------------------------------------------------------- persistence
    def _path(self, name):
        return os.path.join(self.root, name + ".json")
    def _read(self, name, default):
        path = self._path(name)
        if not os.path.exists(path):
            return default
        try:
            with open(path, "r", encoding="utf-8") as handle:
                return json.load(handle)
        except (OSError, ValueError) as exc:
            raise ObsError("cannot read %s.json: %s" % (name, exc))
    def _write(self, name, rows):
        _atomic_write(self._path(name), json.dumps(rows, sort_keys=True, separators=(",", ":")))
    def _dump(self, name, mapping):
        self._write(name, [mapping[key] for key in sorted(mapping)])
    def _load(self):
        rules = self._read("rules", [])
        for rule in rules.values() if isinstance(rules, dict) else rules:
            self._rules[rule["id"]] = rule
        for row in self._read("silences", []):
            self._silences[row["id"]] = row
        for row in self._read("inhibitions", []):
            self._inhibitions[row["id"]] = row
        for row in self._read("slos", []):
            self._slos[(row["tenant"], row["name"])] = row
        for row in self._read("alerts", []):
            row["firing"] = bool(row.get("firing")) and row.get("state") != STATE_RESOLVED
            self._alerts[(row["rule_id"], row["series_id"])] = row
        for key, value in self._read("counters", {}).items():
            if key in self._counters:
                self._counters[key] = max(int(value), self._counters[key])
    # ------------------------------------------------------------------ rules
    def add_rule(self, rule):
        """Validate and store a rule; ``id`` is generated when omitted."""
        if not isinstance(rule, dict):
            raise ObsError("rule must be an object")
        with self._lock:
            self._counters["rule"] += 1
            rid = rule.get("id") or "rule-%04d" % self._counters["rule"]
            clean = self._validate(rule, rid)
            self._rules[rid] = clean
            self._dump("rules", self._rules)
        return copy.deepcopy(clean)
    def _validate(self, rule, rid):
        if not isinstance(rid, str) or not rid:
            raise ObsError("rule id must be a non-empty string")
        for field in ("tenant", "metric"):
            if not isinstance(rule.get(field), str) or not rule[field]:
                raise ObsError("rule %s must be a non-empty string" % field)
        for field, allowed in (("comparator", COMPARATORS), ("agg", AGGREGATES),
                               ("severity", SEVERITIES)):
            if rule.get(field) not in allowed:
                raise ObsError("rule %s must be one of %s" % (field, allowed))
        if not _is_num(rule.get("threshold")):
            raise ObsError("rule threshold must be a number")
        window = _require_int(rule.get("window_ms"), "rule window_ms")
        if window <= 0:
            raise ObsError("rule window_ms must be positive")
        hold = _require_int(rule.get("for_ms", 0), "rule for_ms")
        if hold < 0:
            raise ObsError("rule for_ms must be >= 0")
        annotations = rule.get("annotations") or {}
        if not isinstance(annotations, dict):
            raise ObsError("rule annotations must be an object")
        return {"id": rid, "tenant": rule["tenant"], "metric": rule["metric"],
                "labels": _labels_list(rule.get("labels")), "comparator": rule["comparator"],
                "threshold": float(rule["threshold"]), "for_ms": hold, "window_ms": window,
                "agg": rule["agg"], "severity": rule["severity"],
                "annotations": {str(k): str(v) for k, v in annotations.items()},
                "error": rule.get("error")}
    def list_rules(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._rules[key]) for key in sorted(self._rules)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def del_rule(self, rule_id):
        with self._lock:
            if rule_id not in self._rules:
                raise ObsError("unknown rule: %s" % rule_id)
            del self._rules[rule_id]
            self._dump("rules", self._rules)
        return {"deleted": rule_id}
    # --------------------------------------------------------------- silences
    def add_silence(self, tenant, matcher_labels, starts_ms, ends_ms, reason=""):
        """Record a silence window; it suppresses matching alerts inside it."""
        if not isinstance(tenant, str) or not tenant:
            raise ObsError("silence tenant must be a non-empty string")
        start = _require_int(starts_ms, "silence starts_ms")
        end = _require_int(ends_ms, "silence ends_ms")
        if end <= start:
            raise ObsError("silence ends_ms must be greater than starts_ms")
        with self._lock:
            self._counters["silence"] += 1
            row = {"id": "silence-%04d" % self._counters["silence"], "tenant": tenant,
                   "labels": _labels_list(matcher_labels), "starts_ms": start,
                   "ends_ms": end, "reason": str(reason or "")}
            self._silences[row["id"]] = row
            self._dump("silences", self._silences)
        return copy.deepcopy(row)
    def list_silences(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._silences[key]) for key in sorted(self._silences)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def _active_silence(self, tenant, labels, now_ms):
        for key in sorted(self._silences):
            row = self._silences[key]
            if row["tenant"] == tenant and row["starts_ms"] <= now_ms <= row["ends_ms"] \
                    and matches_labels(labels, dict(row["labels"])):
                return row
        return None
    # ------------------------------------------------------------- inhibition
    def add_inhibition(self, source_severity, target_severity, same_labels=True):
        """Higher-severity firing alerts suppress matching lower-severity ones."""
        for field, value in (("source_severity", source_severity),
                             ("target_severity", target_severity)):
            if value not in SEVERITIES:
                raise ObsError("%s must be one of %s" % (field, SEVERITIES))
        if SEVERITY_RANK[source_severity] <= SEVERITY_RANK[target_severity]:
            raise ObsError("source_severity must be strictly higher than target_severity")
        if not isinstance(same_labels, bool):
            raise ObsError("same_labels must be a boolean")
        with self._lock:
            self._counters["inhibition"] += 1
            row = {"id": "inhibition-%04d" % self._counters["inhibition"],
                   "source_severity": source_severity, "target_severity": target_severity,
                   "same_labels": same_labels}
            self._inhibitions[row["id"]] = row
            self._dump("inhibitions", self._inhibitions)
        return copy.deepcopy(row)
    def list_inhibitions(self):
        with self._lock:
            return [copy.deepcopy(self._inhibitions[key]) for key in sorted(self._inhibitions)]
    def _inhibited(self, severity, tenant, labels, rule_id, series_id):
        """Id of the firing alert that inhibits this one, or None.

        Equal label sets (the empty set included) are required when
        ``same_labels`` is set; otherwise the source set must be a subset.
        """
        wanted = frozenset((key, str(value)) for key, value in labels.items())
        rules = [row for row in self._inhibitions.values() if row["target_severity"] == severity]
        if not rules:
            return None
        for key in sorted(self._alerts):
            other = self._alerts[key]
            if other["state"] != STATE_FIRING or other["tenant"] != tenant:
                continue
            if (other["rule_id"], other["series_id"]) == (rule_id, series_id):
                continue
            other_labels = frozenset((k, str(v)) for k, v in other["labels"].items())
            for row in rules:
                if SEVERITY_RANK[other["severity"]] < SEVERITY_RANK[row["source_severity"]]:
                    continue
                if other_labels == wanted or (not row["same_labels"] and other_labels <= wanted):
                    return other["id"]
        return None
    # --------------------------------------------------------------- evaluate
    def _condition(self, rule, series_id, now_ms):
        """Buckets of one series inside the rule window, plus the hold decision.

        The window is ``[bucket_start(now_ms) - window_ms, now_ms]`` with
        ``bucket_start(t) = t - (t % window_ms)``: the running bucket plus the
        whole previous one. The condition holds when every non-empty bucket in
        the window satisfies the comparator; ``held_ms`` spans the unbroken run
        of satisfying buckets ending at the last bucket.
        """
        step = rule["window_ms"]
        buckets = labels = None
        for item in self.store.query(
                rule["tenant"], rule["metric"], labels=dict(rule["labels"]),
                start_ms=now_ms - (now_ms % step) - step, end_ms=now_ms,
                step_ms=step, agg=rule["agg"]):
            if item["series_id"] == series_id:
                buckets, labels = item["points"], item["labels"]
                break
        values = [point[1] for point in buckets or [] if point[1] is not None]
        if not values:
            return None
        satisfied = [compare(value, rule["comparator"], rule["threshold"]) for value in values]
        if not all(satisfied):
            return {"hold": False, "labels": labels, "observed": values[-1]}
        run = 0
        for index in range(len(satisfied) - 1, -1, -1):
            if not satisfied[index]:
                run = index + 1
                break
        held = int(buckets[-1][0]) - int(buckets[run][0])
        return {"hold": True, "labels": labels, "observed": values[-1],
                "run_start": int(buckets[run][0]), "held_ms": held,
                "for_satisfied": held >= rule["for_ms"]}
    def evaluate(self, now_ms):
        """Evaluate every rule at ``now_ms`` -> firing/silenced/inhibited/resolved."""
        now = _require_int(now_ms, "now_ms")
        out = {STATE_FIRING: [], STATE_SILENCED: [], STATE_INHIBITED: [], STATE_RESOLVED: []}
        with self._lock:
            for rule in self.list_rules():
                if rule.get("error"):
                    raise ObsError("cannot evaluate rule %s: %s" % (rule["id"], rule["error"]))
                step = rule["window_ms"]
                for sid, _ in self.store._scan(
                        rule["tenant"], rule["metric"], dict(rule["labels"]),
                        now - (now % step) - step, now):
                    state = self._condition(rule, sid, now)
                    if state is None:
                        continue
                    key = (rule["id"], sid)
                    alert = self._alerts.get(key)
                    if not state["hold"]:
                        if alert is not None and alert["state"] in ACTIVE_STATES:
                            alert.update(state=STATE_RESOLVED, firing=False, resolved_ms=now)
                            out[STATE_RESOLVED].append(copy.deepcopy(alert))
                        continue
                    if alert is None:
                        alert = {"id": self._next_alert_id(), "rule_id": rule["id"],
                                 "tenant": rule["tenant"], "metric": rule["metric"],
                                 "series_id": sid, "labels": dict(state["labels"]),
                                 "severity": rule["severity"], "occurrences": 0,
                                 "annotations": copy.deepcopy(rule["annotations"]),
                                 "state": STATE_FIRING}
                        self._alerts[key] = alert
                    alert.update(occurrences=int(alert.get("occurrences", 0)) + 1, firing=True,
                                 since_ms=state["run_start"], last_eval_ms=now,
                                 observed=state["observed"], held_ms=state["held_ms"])
                    if not state["for_satisfied"]:
                        continue
                    silence = self._active_silence(rule["tenant"], state["labels"], now)
                    blocker = None if silence else self._inhibited(
                        alert["severity"], rule["tenant"], state["labels"], rule["id"], sid)
                    if silence is not None:
                        alert.update(state=STATE_SILENCED, silenced_by=silence["id"],
                                     silence_reason=silence["reason"])
                        out[STATE_SILENCED].append(copy.deepcopy(alert))
                    elif blocker is not None:
                        alert.update(state=STATE_INHIBITED, inhibited_by=blocker)
                        out[STATE_INHIBITED].append(copy.deepcopy(alert))
                    else:
                        alert.update(state=STATE_FIRING)
                        alert.pop("silenced_by", None)
                        alert.pop("inhibited_by", None)
                        out[STATE_FIRING].append(copy.deepcopy(alert))
            self._write("alerts", [self._alerts[k] for k in
                                   sorted(self._alerts, key=lambda k: (k[0], k[1]))])
            self._write("counters", self._counters)
        for rows in out.values():
            rows.sort(key=lambda row: row["id"])
        return out
    def _next_alert_id(self):
        self._counters["alert"] += 1
        return "alert-%05d" % self._counters["alert"]
    # ----------------------------------------------------------------- alerts
    def list_alerts(self, tenant=None, state=None):
        with self._lock:
            rows = [copy.deepcopy(self._alerts[key]) for key in sorted(self._alerts)]
        return [row for row in rows
                if (tenant is None or row["tenant"] == tenant)
                and (state is None or row["state"] == state)]
    def get_alert(self, alert_id):
        with self._lock:
            for row in self._alerts.values():
                if row["id"] == alert_id:
                    return copy.deepcopy(row)
        raise ObsError("unknown alert: %s" % alert_id)
    # -------------------------------------------------------------------- SLO
    def set_slo(self, tenant, name, metric, labels, good_comparator, threshold,
                target_ratio, window_ms):
        """Define a good-events ratio SLO over a sliding ``window_ms``."""
        for field, value in (("tenant", tenant), ("name", name), ("metric", metric)):
            if not isinstance(value, str) or not value:
                raise ObsError("slo %s must be a non-empty string" % field)
        if good_comparator not in COMPARATORS:
            raise ObsError("good_comparator must be one of %s" % (COMPARATORS,))
        if not _is_num(threshold):
            raise ObsError("slo threshold must be a number")
        if not _is_num(target_ratio) or not 0.0 < float(target_ratio) <= 1.0:
            raise ObsError("target_ratio must be in (0, 1]")
        window = _require_int(window_ms, "slo window_ms")
        if window <= 0:
            raise ObsError("slo window_ms must be positive")
        row = {"tenant": tenant, "name": name, "metric": metric,
               "labels": _labels_list(labels), "good_comparator": good_comparator,
               "threshold": float(threshold), "target_ratio": float(target_ratio),
               "window_ms": window}
        with self._lock:
            self._slos[(tenant, name)] = row
            self._dump("slos", self._slos)
        return copy.deepcopy(row)
    def _find_slo(self, name, tenant=None):
        with self._lock:
            if tenant is not None and (tenant, name) in self._slos:
                return copy.deepcopy(self._slos[(tenant, name)])
            matches = [self._slos[key] for key in sorted(self._slos) if key[1] == name]
        if not matches:
            raise ObsError("unknown slo: %s" % name)
        if len(matches) > 1 and tenant is None:
            raise ObsError("slo %s exists for several tenants; pass tenant" % name)
        return matches[0]
    def list_slos(self, tenant=None):
        with self._lock:
            rows = [copy.deepcopy(self._slos[key]) for key in sorted(self._slos)]
        return [row for row in rows if tenant is None or row["tenant"] == tenant]
    def slo_status(self, name, now_ms, tenant=None):
        """Event-ratio SLO status over ``[now_ms - window_ms, now_ms]``.

        Every stored sample in the window is one event: ``total`` counts them,
        ``good`` counts those satisfying the good comparator, ``bad = total -
        good``.

            ratio        = good / total                            (0.0 if total == 0)
            error_budget = max(0, 1 - (1 - ratio) / (1 - target))  (target < 1)
            burn_rate    = (bad / total) / (1 - target)            (0.0 if target >= 1)
            met          = ratio >= target
        """
        now = _require_int(now_ms, "now_ms")
        slo = self._find_slo(name, tenant)
        total = good = 0
        for _, rows in self.store._scan(slo["tenant"], slo["metric"], dict(slo["labels"]),
                                        now - slo["window_ms"], now):
            for _, value in rows:
                total += 1
                if compare(value, slo["good_comparator"], slo["threshold"]):
                    good += 1
        bad = total - good
        target = float(slo["target_ratio"])
        ratio = (good / float(total)) if total else 0.0
        allowed_bad = 1.0 - target
        if allowed_bad > 0.0:
            error_budget = max(0.0, 1.0 - ((1.0 - ratio) / allowed_bad))
        else:
            error_budget = 1.0 if ratio >= 1.0 else 0.0
        burn_rate = ((bad / float(total)) / allowed_bad) if (allowed_bad > 0.0 and total) else 0.0
        return {"tenant": slo["tenant"], "name": slo["name"], "window_ms": slo["window_ms"],
                "total": total, "good": good, "bad": bad, "ratio": ratio,
                "target_ratio": target, "error_budget": error_budget,
                "burn_rate": burn_rate, "met": ratio >= target}

