        rows = store.query(_require(params, "tenant"), _require(params, "metric"), labels=labels,
                           start_ms=_int(params.get("start"), "start"),
                           end_ms=_int(params.get("end"), "end"),
                           step_ms=_int(params.get("step"), "step"),
